/* @lc app=leetcode id=2858 lang=kotlin */ class Solution { fun minEdgeReversals(n: Int, edges: Array<IntArray>): IntArray = edges.flatMap { (a, b) -> listOf(a to (b to 0), b to (a to 1)) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> IntArray(n).let { ans -> IntArray(n).let { pw -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { (v, _) -> par[v] == -1 }.map { (v, w) -> true.also { par[v] = u }.also { ans[v] = ans[u] + 1 - 2 * w }.also { pw[v] = w }.let { v } } }.takeIf { it.isNotEmpty() } }.count().let { pw.sum().let { base -> ans.map { it + base }.toIntArray() } } } } } } }